// Lógica de Normalización de Frecuencia (Base 60)
return items.map(item => {
  const disonanciaRaw = item.json.disonancia || 0;
  const axiones = item.json.axiones_count || 0;

  // Convertimos la disonancia a una métrica armónica
  // 3600 es el cuadrado de 60, representando un ciclo completo de la matriz
  const factorArmonico = (disonanciaRaw * 60) % 3600;

  return {
    json: {
      source_signal: item.json,
      vector_fase: factorArmonico,
      pureza_matriz: parseFloat((1 - (disonanciaRaw / 3600)).toFixed(4)),
      es_axion: axiones > 0,
      timestamp_quantum: Date.now(),
      _meta: {
        sync_type: "base60_harmonic",
        version: "1.1"
      }
    }
  };
});

// 🏛️ Cámara de Eco: Generador de Resonancia
// Transforma la pureza matemática en experiencia sensorial (Sonido/Color)

const itemsWithEcho = items.map(item => {
  const pureza = item.json.pureza_matriz;
  const disonancia = item.json.source_signal.disonancia;

  // 🎵 Cálculo de Frecuencia (Sonido)
  // Base: 432Hz (Tono de curación/natural)
  // Modulador: La disonancia distorsiona la frecuencia hacia arriba
  // Si pureza = 1.0 (Disonancia 0) -> 432 Hz
  // Si pureza < 0.5 -> Tono de alerta (e.g. 550 Hz, 800 Hz)
  const baseFreq = 432;
  const freqShift = disonancia * 5; // Cada evento aumenta 5Hz
  const targetFreq = baseFreq + freqShift;

  // 🎨 Cálculo de Espectro (Color)
  // HSL: Cyan (180) es estado puro. Rojo (0) es crítico.
  // Interpolamos de 180 a 0 basado en la pureza.
  const hue = Math.floor(pureza * 180); // 1.0 * 180 = 180 (Cyan), 0.0 * 180 = 0 (Red)
  const colorHex = `hsl(${hue}, 100%, 50%)`;

  // Nivel de intensidad para UI
  let intensity = "calm";
  if (pureza < 0.9) intensity = "disturbance";
  if (pureza < 0.5) intensity = "critical";

  return {
    json: {
      ...item.json,
      echo_chamber: {
        frequency_hz: targetFreq,
        visual_color_hsl: colorHex,
        hue: hue,
        intensity: intensity,
        waveform: pureza > 0.9 ? "sine" : "sawtooth" // Sine es suave, Sawtooth es agresivo
      }
    }
  };
});

return itemsWithEcho;
